from decimal import Decimal, ROUND_HALF_UP

_CENTS = Decimal("0.01")


def _round_cents(value):
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def invoice(lines, tax_rate):
    rate = Decimal(tax_rate)

    rounded_lines = []
    for row in lines:
        ext = Decimal(row["unit_price"]) * row["qty"]
        rounded_ext = _round_cents(ext)
        rounded_lines.append((row["taxable"], rounded_ext))

    subtotal = sum((rounded_ext for _, rounded_ext in rounded_lines), Decimal("0"))

    tax = Decimal("0")
    for taxable, rounded_ext in rounded_lines:
        if taxable:
            tax += _round_cents(rounded_ext * rate)

    total = subtotal + tax

    return {
        "subtotal": f"{subtotal:.2f}",
        "tax": f"{tax:.2f}",
        "total": f"{total:.2f}",
    }
